CREATE TABLE skill_definition (id UUID PRIMARY KEY, code VARCHAR(80) NOT NULL UNIQUE, display_name VARCHAR(160) NOT NULL, legacy_stage_type VARCHAR(50), active BOOLEAN NOT NULL, display_order INTEGER NOT NULL, created_at TIMESTAMP WITH TIME ZONE NOT NULL, updated_at TIMESTAMP WITH TIME ZONE NOT NULL, CONSTRAINT chk_skill_order CHECK(display_order > 0));
CREATE TABLE mode_skill_requirement (id UUID PRIMARY KEY, learning_mode VARCHAR(50) NOT NULL, skill_definition_id UUID NOT NULL, display_order INTEGER NOT NULL, applicability VARCHAR(20) NOT NULL, assistance_allowed BOOLEAN NOT NULL, stop_on_failure BOOLEAN NOT NULL, completion_required BOOLEAN NOT NULL, CONSTRAINT uq_mode_skill_order UNIQUE(learning_mode, display_order), CONSTRAINT fk_mode_requirement_skill FOREIGN KEY(skill_definition_id) REFERENCES skill_definition(id));
CREATE TABLE curriculum_item (id UUID PRIMARY KEY, problem_id UUID NOT NULL, pattern_id UUID NOT NULL, role VARCHAR(40) NOT NULL, display_order INTEGER NOT NULL, active BOOLEAN NOT NULL, notes CLOB, CONSTRAINT uq_curriculum_problem_pattern_role UNIQUE(problem_id,pattern_id,role), CONSTRAINT fk_curriculum_problem FOREIGN KEY(problem_id) REFERENCES problem(id), CONSTRAINT fk_curriculum_pattern FOREIGN KEY(pattern_id) REFERENCES pattern(id));
CREATE TABLE problem_exposure (id UUID PRIMARY KEY, problem_id UUID NOT NULL UNIQUE, state VARCHAR(40) NOT NULL, first_exposed_at TIMESTAMP WITH TIME ZONE, last_exposed_at TIMESTAMP WITH TIME ZONE, created_at TIMESTAMP WITH TIME ZONE NOT NULL, updated_at TIMESTAMP WITH TIME ZONE NOT NULL, CONSTRAINT fk_exposure_problem FOREIGN KEY(problem_id) REFERENCES problem(id));
CREATE TABLE learning_session (id UUID PRIMARY KEY, problem_id UUID NOT NULL, suggested_mode VARCHAR(50), selected_mode VARCHAR(50), prior_exposure_snapshot VARCHAR(40), status VARCHAR(20) NOT NULL, time_box_seconds BIGINT, legacy_attempt_id UUID, creation_reason VARCHAR(255), started_at TIMESTAMP WITH TIME ZONE, completed_at TIMESTAMP WITH TIME ZONE, created_at TIMESTAMP WITH TIME ZONE NOT NULL, updated_at TIMESTAMP WITH TIME ZONE NOT NULL, CONSTRAINT fk_session_problem FOREIGN KEY(problem_id) REFERENCES problem(id), CONSTRAINT fk_session_attempt FOREIGN KEY(legacy_attempt_id) REFERENCES attempts(id) ON DELETE SET NULL, CONSTRAINT chk_session_timebox CHECK(time_box_seconds IS NULL OR time_box_seconds > 0));
CREATE TABLE content_exposure_event (id UUID PRIMARY KEY, problem_id UUID, pattern_id UUID, learning_session_id UUID, exposure_type VARCHAR(40) NOT NULL, content_reference VARCHAR(255), exposed_at TIMESTAMP WITH TIME ZONE NOT NULL, CONSTRAINT fk_content_problem FOREIGN KEY(problem_id) REFERENCES problem(id), CONSTRAINT fk_content_pattern FOREIGN KEY(pattern_id) REFERENCES pattern(id), CONSTRAINT fk_content_session FOREIGN KEY(learning_session_id) REFERENCES learning_session(id) ON DELETE SET NULL);
CREATE INDEX idx_curriculum_item_pattern_role ON curriculum_item(pattern_id,role); CREATE INDEX idx_content_exposure_problem ON content_exposure_event(problem_id,exposed_at); CREATE INDEX idx_learning_session_problem ON learning_session(problem_id,created_at);
